// Catalogue of real game models available for procedural content.
//
// Source of truth is assets/objects_db.json, generated by tools/parse_ide.py
// from the game's own .ide/.col files. The catalogue never invents model ids:
// if a tag is missing the generator degrades gracefully instead of spawning
// garbage.
#pragma once

#include "json.hpp"
#include "types.hpp"

#include <string>
#include <vector>

namespace usa1to1 {
namespace core {

enum class PropTag {
    Unknown = 0,
    Building,
    Tree,
    Prop,
    RoadFlat,
    Furniture,
    Door,
    Wall,
    Floor,
    StreetLight,
};

const char *PropTagName(PropTag tag);
PropTag PropTagFromName(const std::string &name);

struct ModelProto {
    int id = -1;
    std::string name;
    PropTag tag = PropTag::Unknown;
    // Real collision bounds from the .col file (half-extents, metres).
    Vec3f colHalfExtents{1.0f, 1.0f, 1.0f};
    Vec3f colOffset;
    float drawDistance = 200.0f;
    bool isRoad = false;   // CBaseModelInfo::bIsRoad
    bool hasCollision = true;
    bool isDynamic = false; // vehicles / peds, never used for static chunks
};

// A road must support a player, not just have a large bounding sphere.
bool IsFlatRoadCandidate(const ModelProto &proto);

class ModelCatalog {
  public:
    ModelCatalog() = default;
    ModelCatalog(const ModelCatalog &other) { CopyFrom(other); }
    ModelCatalog &operator=(const ModelCatalog &other) {
        if (this != &other) {
            m_protos.clear();
            CopyFrom(other);
        }
        return *this;
    }
    ModelCatalog(ModelCatalog &&) noexcept = default;
    ModelCatalog &operator=(ModelCatalog &&) noexcept = default;

    bool LoadFromJson(const Json &root, std::string *error = nullptr);
    bool LoadFromFile(const std::string &path, std::string *error = nullptr);
    Json ToJson() const;

    void Add(const ModelProto &proto);
    void AddModels(std::vector<ModelProto> protos);
    const std::vector<ModelProto> &All() const { return m_protos; }
    void Clear();
    size_t Size() const { return m_protos.size(); }

    const ModelProto *Find(int id) const;
    // Deterministic pick from a tag bucket; returns nullptr when empty.
    const ModelProto *PickByTag(PropTag tag, uint64_t rngValue) const;
    const std::vector<const ModelProto *> &ByTag(PropTag tag) const;
    // Buckets that contain at least one usable (collidable) model.
    const std::vector<const ModelProto *> &Buildings() const { return ByTag(PropTag::Building); }
    const ModelProto *PickRoad(int tableRoad = -1, int whitelistRoad = -1) const;

    bool HasTag(PropTag tag) const { return !ByTag(tag).empty(); }

    // Builds a small built-in fallback catalogue so a fresh install still works
    // before tools/parse_ide.py has ever run on the device.
    static ModelCatalog MakeFallback();

  private:
    void RebuildBuckets();
    void CopyFrom(const ModelCatalog &other) {
        m_protos = other.m_protos;
        RebuildBuckets();
    }

    std::vector<ModelProto> m_protos;
    std::vector<const ModelProto *> m_buckets[static_cast<int>(PropTag::StreetLight) + 1];
};

} // namespace core
} // namespace usa1to1
